import raw from "@/data/deer-hunt-areas.json";
import { DemandDraw, MapArea, PointsDraw, RegionDraws, neighborsIn } from "@/lib/hunts";
import type { License } from "@/lib/license";

// Generated by scripts/hunts/build_hunt_data.py from WGFD's deer draw reports,
// Chapter 6 (deer seasons and boundaries) and the 2026 deer hunt-area layer.
// Server-only, like lib/elk.ts.

export interface Season {
  archery: [string, string] | null; // special archery opens, closes
  opens: string; // "Oct. 1"
  closes: string;
  quota: number | "Unlimited" | null; // null on general seasons and follow-on rows of a type
  limitations: string; // what the license allows, as Chapter 6 words it
}

export interface DeerHunt {
  type: string;
  description: string;
  doeFawn: boolean;
  seasons: Season[];
  nrPoints?: PointsDraw;
  nrRandom?: DemandDraw;
  nrSpecialPoints?: PointsDraw;
  nrSpecialRandom?: DemandDraw;
  nrDoeFawn?: DemandDraw;
  resident?: DemandDraw;
  residentDoeFawn?: DemandDraw;
}

export interface DeerArea extends MapArea {
  muleDeerHerd: { unit: number; name: string } | null;
  whitetailHerd: { unit: number; name: string } | null;
  region: string; // nonresident general-license region, "A" to "Y"
  sqMiles: number;
  hunts: DeerHunt[];
  general: Season[]; // general-license seasons; empty in limited-quota-only areas
  closed: boolean;
  boundary: string | null;
}

interface DeerData {
  year: number;
  sources: { odds: string; boundaries: string; seasons: string };
  nrRegions: Record<string, RegionDraws>;
  areas: DeerArea[];
}

const data = raw as unknown as DeerData;

export const DEER_YEAR = data.year;
export const DEER_SOURCES = data.sources;
export const DEER_AREAS = data.areas;
export const DEER_REGIONS = Object.entries(data.nrRegions).map(([region, draws]) => ({
  region,
  draws,
  areas: DEER_AREAS.filter((a) => a.region === region),
  // Where the region's general license is valid: areas with a general season.
  generalAreas: DEER_AREAS.filter((a) => a.region === region && a.general.length > 0),
}));
export type DeerRegion = (typeof DEER_REGIONS)[number];

export const deerPath = (a: Pick<DeerArea, "area">) => `/hunting/deer/area-${a.area}`;
export const regionPath = (region: string) => `/hunting/deer/region-${region.toLowerCase()}`;

export function getDeerPage(slug: string): { area: DeerArea } | { region: DeerRegion } | undefined {
  const a = /^area-(\d+)$/.exec(slug);
  if (a) {
    const area = DEER_AREAS.find((x) => x.area === Number(a[1]));
    return area && { area };
  }
  const r = /^region-([a-z])$/.exec(slug);
  const region = r && DEER_REGIONS.find((x) => x.region === r[1].toUpperCase());
  return region ? { region } : undefined;
}

export const deerSlugs = () => [
  ...DEER_AREAS.map((a) => deerPath(a).split("/").pop()!),
  ...DEER_REGIONS.map((r) => regionPath(r.region).split("/").pop()!),
];

export const getRegion = (region: string) => DEER_REGIONS.find((r) => r.region === region);

// The headline limited-quota hunt: the first antlered or any-deer type, else the first hunt.
export function mainHunt(a: DeerArea): DeerHunt | undefined {
  return a.hunts.find((h) => !h.doeFawn) ?? a.hunts[0];
}

export function seasonDates(s: Season): string {
  return `${s.opens} to ${s.closes}`;
}

export function herdNames(a: DeerArea): string {
  return [a.muleDeerHerd?.name, a.whitetailHerd?.name]
    .filter((n, i, all): n is string => !!n && all.indexOf(n) === i)
    .join(" and ");
}

export const neighbors = (a: DeerArea) => neighborsIn(DEER_AREAS, a);

const pad = (n: number) => String(n).padStart(3, "0");

function huntLicense(a: DeerArea, h: DeerHunt): License {
  const s = h.seasons[0];
  return {
    id: `type-${h.type}`,
    kicker: `Type ${h.type}`,
    title: h.description,
    serial: `D-${pad(a.area)}-${h.type}`,
    points: h.nrPoints,
    random: h.nrRandom,
    demand: h.nrDoeFawn ?? (h.nrPoints ? undefined : h.nrRandom),
    resident: h.resident ?? h.residentDoeFawn,
    note: s ? seasonDates(s) : undefined,
  };
}

// A region's nonresident general license, and its special (higher-priced) version.
export function regionLicenses(r: DeerRegion): License[] {
  const out: License[] = [];
  if (r.draws.nrPoints || r.draws.nrRandom) {
    out.push({
      id: "general",
      kicker: `Region ${r.region}`,
      title: "General license",
      serial: `D-${r.region}-GEN`,
      points: r.draws.nrPoints,
      random: r.draws.nrRandom,
      demand: r.draws.nrPoints ? undefined : r.draws.nrRandom,
    });
  }
  if (r.draws.nrSpecialPoints || r.draws.nrSpecialRandom) {
    out.push({
      id: "special",
      kicker: `Region ${r.region}`,
      title: "Special license",
      serial: `D-${r.region}-SPL`,
      points: r.draws.nrSpecialPoints,
      random: r.draws.nrSpecialRandom,
      demand: r.draws.nrSpecialPoints ? undefined : r.draws.nrSpecialRandom,
    });
  }
  return out;
}

// What a nonresident can apply for to hunt an area: the region's general
// license where the area has a general season, then its limited-quota types.
export function deerLicenses(a: DeerArea): License[] {
  const region = getRegion(a.region);
  const general =
    a.general.length && region
      ? regionLicenses(region)
          .slice(0, 1)
          .map((l) => ({ ...l, note: seasonDates(a.general[0]) }))
      : [];
  const main = mainHunt(a);
  const hunts = [...a.hunts].sort((x, y) => (x === main ? -1 : y === main ? 1 : 0)).map((h) => huntLicense(a, h));
  return [...general, ...hunts];
}
